# frozen_string_literal: true

# Generated by `bin/rails generate current_scope:identity` (#158).
#
# This object is config.subject_identity, not config.subject_label.
# Label is display-only and fail-soft. Identity is load-bearing: a
# duplicate natural key raises, and resolve never inserts a subject.
#
# Fill identify/resolve for a key split across tables (users joined to
# contacts). For a single column, prefer `config.subject_identity = :email`
# instead of this class.
#
# Placeholder rows created by current_scope:identity:setup PLACEHOLDER=1 WRITE=1
# must be stamped with CurrentScope::SubjectIdentity::PLACEHOLDER_MARK
# ("current_scope_placeholder") so you can find and delete them.
# Production never creates one.
class CurrentScopeSubjectIdentity
  def identify(subject)
    subject.email
  end

  def resolve(key)
    return if key.blank?

    rows = User.where(email: key).limit(2).to_a
    case rows.size
    when 0 then nil
    when 1 then rows.first
    else
      raise CurrentScope::ConfigurationError,
            "subject_identity matched more than one User for #{key.inspect}"
    end
  end

  def unique?
    !User.where.not(email: [ nil, "" ]).group(:email).having("COUNT(*) > 1").exists?
  end

  def create_placeholder!(key)
    User.create!(
      email: key,
      name: "#{CurrentScope::SubjectIdentity::PLACEHOLDER_MARK} #{key}"
    )
  end
end
